#include "BombReimu.hpp"
#include "AnmVisualState.hpp"
#include <algorithm>
#include <cmath>
namespace th17 {
bool BombReimu::start(){position=context.motion.position;if(!sound(49,true))return false;invalidate_spell();context.session.roaring_breaks=wrapping_add(context.session.roaring_breaks,1);orbs=std::make_unique<std::array<BombOrb,24>>();aura_handle=animation(37,position);return aura_handle!=0;}
bool BombReimu::create_orbs(u32 first,bool clockwise,i32 amount){float angle=0;for(u32 i=0;i<8;i++){auto& orb=(*orbs)[first+i];orb.motion.velocity=context.motion.position;orb.handle=animation(context.session.animal==1?23:22,orb.motion.position);if(!orb.handle)return false;orb.active=true;orb.age.set(0);orb.index=i;auto* source=circle(orb.motion.position,56,0,9999,amount,&orb.damage_id);if(!source)return false;source->interval=3;source->damage_limit=400;orb.motion.speed=0;orb.motion.flags=(orb.motion.flags&~13u)|2;orb.motion.angle=normalize_angle(angle);orb.motion.angular_velocity=clockwise?0.04908738657832146f:-0.04908738657832146f;orb.turn_speed=clockwise?0.10471975803375244f:-0.10471975803375244f;angle=normalize_angle(float(angle+0.78539818525314331f));}return true;}
bool BombReimu::update_orb(BombOrb& orb){
    auto& motion=orb.motion;
    if(orb.age.current!=orb.age.previous){if(orb.age.current<90){motion.velocity=context.motion.position;motion.radius=float(motion.radius+1.5f);motion.set_angle(float(motion.angle+orb.turn_speed));}else if(orb.age.current<wrapping_mul(wrapping_add(orb.index,9),10)){motion.velocity=context.motion.position;motion.set_angle(float(motion.angle+orb.turn_speed));}else if(orb.age.current==wrapping_mul(wrapping_add(orb.index,9),10)){motion.flags&=~15u;motion.set_angle(float(std::atan2(double(orb.last_velocity.y),double(orb.last_velocity.x))));motion.speed=float(std::sqrt(double(float(float(orb.last_velocity.x*orb.last_velocity.x)+float(orb.last_velocity.y*orb.last_velocity.y)))));}else{BombTarget target;if(!context.world.nearest_target(motion.position,512,target))return fail("Reimu bomb target unavailable");orb.target=target.id;if(orb.target){if(!(target.flags&0xc000021)){const float desired=float(std::atan2(double(float(target.position.y-motion.position.y)),double(float(target.position.x-motion.position.x))));float difference=float(desired-motion.angle);if(difference>3.14159274101257324f)difference=float(desired-float(motion.angle+6.28318548202514648f));else if(float(motion.angle-desired)>3.14159274101257324f)difference=float(desired-float(motion.angle-6.28318548202514648f));const float magnitude=std::abs(difference);float speed=motion.speed;if(magnitude<0.78539818525314331f){if(magnitude<0.26179939508438110f)speed=std::min(float(speed+.2f),8.f);}else speed=std::max(float(speed-.7f),1.f);motion.set_angle(float(motion.angle+float(difference*.1f)));motion.speed=speed;}}else if(motion.position.x<-160||motion.position.x>160||motion.position.y<32||motion.position.y>416)motion.speed=float(motion.speed*.9f);}}
    const auto old=motion.position;motion.integrate(rate);motion.advance(rate);if(auto* vm=context.animations.registry.find(orb.handle))vm->visual.translation=motion.position;orb.last_velocity={float(motion.position.x-old.x),float(motion.position.y-old.y),float(motion.position.z-old.z)};orb.age.tick(&rate);return true;
}
bool BombReimu::explode(BombOrb& orb){if(orb.retired)return context.animations.retire(orb.handle)||fail(context.animations.error);if(orb.active){if(!sound(27)||!context.world.cancel_bullets(orb.motion.position,128,0,true)||!context.world.cancel_lasers(orb.motion.position,128,1,true))return fail("Reimu bomb explosion cancellation failed");if(!circle(orb.motion.position,64,8,11,100))return false;}if(!interrupt(orb.handle))return false;orb.active=false;if(auto* damage=context.damage.find(orb.damage_id))damage->flags&=~1u;orb.damage_id=0;return true;}
bool BombReimu::clear_orbs(){if(!orbs)return true;for(auto& orb:*orbs)if(!explode(orb))return false;return true;}
bool BombReimu::cancel(){for(u32 i=0;i<orbs->size();i++){auto& orb=(*orbs)[i];if(orb.active&&age.current%8==i32(i&7)){if(!context.world.cancel_bullets(orb.motion.position,64,0,true)||!context.world.cancel_lasers(orb.motion.position,64,0,true))return fail("Reimu bomb cancellation failed");}}return true;}
bool BombReimu::frame(bool& finished){
    if(!orbs)return fail("Reimu bomb orb owner unavailable");context.invulnerability.set(40);if(auto* aura=context.animations.registry.find(aura_handle))aura->visual.translation=context.motion.position;
    if(age.current>119){bool found=false;for(auto& orb:*orbs){if(context.animations.registry.find(orb.handle)){found=true;break;}orb.handle=0;}if(!found){if(!interrupt(aura_handle))return false;orbs.reset();finished=true;return true;}}
    if(age.current==(context.session.animal==1?400:200)){return clear_orbs()&&interrupt(aura_handle)&&(context.world.screen_effect({1,8,6,6,0})||fail("Bomb screen effect unavailable"));}
    if(age.current!=age.previous){if(age.current==0){if(!create_orbs(0,true,15))return false;}else if(context.session.animal==1&&age.current==80){if(!sound(44)||!create_orbs(8,false,7))return false;}else if(context.session.animal==1&&age.current==160){if(!sound(44)||!create_orbs(16,true,7))return false;}}
    for(auto& orb:*orbs)if(orb.active){if(!update_orb(orb))return false;auto* damage=context.damage.find(orb.damage_id);if(!damage)return fail("Reimu bomb damage source unavailable");if(damage->accumulated<400)damage->motion.position=orb.motion.position;else{if(!explode(orb)||!sound(27))return false;if(!context.world.screen_effect({1,8,6,6,0}))return fail("Bomb screen effect unavailable");}}return cancel();
}
bool BombReimu::stop(){if(!clear_orbs()||!interrupt(aura_handle))return false;orbs.reset();if(!context.world.screen_effect({1,8,6,6,0}))return fail("Bomb screen effect unavailable");context.session.bomb_state=0;return true;}
}
